(()=>{
 const panel=document.createElement('details');panel.id='advanced-authoring-panel';panel.className='advanced';panel.innerHTML='<summary>Whole effect & Unreal scene</summary><h3>Whole effect controls</h3><label>Intensity (×)<input id="master-intensity" type="number" min="0" max="10" step=".1"></label><label>Scale (×)<input id="master-scale" type="number" min=".1" max="10" step=".1"></label><label>Color tint<input id="master-color" type="color"></label><button id="master-reset">Reset whole-effect controls</button><small>Applies to every current layer. Tint multiplies its original colors.</small><h3>Selected layer in Unreal</h3><label>Simulation<select id="layer-simulation"><option value="cpu">CPU — supports event responses</option><option value="gpu">GPU — larger particle counts</option></select></label><label>GPU particle amount<input id="gpu-amount" type="number" min="5" max="100000" step="1" value="5000"></label><small>Continuous flow uses this amount per second; Burst emits twice this amount. GPU target runs in Unreal. Ember previews up to 2,000 particles per second, with a 16,000 particle cap.</small><label>Scene collisions<select id="scene-collision"><option value="off">Off</option><option value="bounce">Bounce off scene geometry</option><option value="kill">Disappear on contact</option></select></label><button id="read-scene-assets">Read connected project assets</button><label>Emit from a mesh surface<select id="surface-asset"><option value="">Original spawn shape</option></select></label><label>Unreal level<select id="attachment-map"><option value="">Choose a level to read its actors</option></select></label><label>Follow an actor (whole effect)<select id="attachment-actor"><option value="">No attachment</option></select></label><label>Attachment socket<select id="attachment-socket"><option value="">Actor / mesh origin</option></select></label><p id="scene-authoring-status" class="animation-intro"></p><small>Ember and Blender preview a saved reference surface. Animated character sampling, actor following and scene geometry collisions run in Unreal. Export creates a companion actor for attachments; place it in the selected level.</small><button id="scene-authoring-help">Help with scene features</button>';
 $('#animation-panel').before(panel);let assets=[],actors=[],project;
 function refresh(){const m={...EmberAdvancedAuthoring.defaults,...state.master};for(const key of ['intensity','scale','color'])$('#master-'+key).value=m[key];$('#layer-simulation').value=state.simulation||'cpu';$('#gpu-amount').value=state.gpuAmount||5000;$('#gpu-amount').disabled=state.simulation!=='gpu';$('#scene-collision').value=state.sceneCollision||'off';$('#surface-asset').value=state.surface?.asset||'';if(state.surface&&!assets.some(a=>a.asset===state.surface.asset)){const o=new Option(state.surface.asset,state.surface.asset);$('#surface-asset').add(o);$('#surface-asset').value=o.value;}for(const [id,value]of [['attachment-actor',state.attachment?.actor],['attachment-socket',state.attachment?.socket]]){const select=$('#'+id);if(value&&![...select.options].some(o=>o.value===value))select.add(new Option(value,value));select.value=value||'';}if(state.surface)$('#advanced-shape').disabled=true;}
 function master(){const m={intensity:$('#master-intensity').valueAsNumber,scale:$('#master-scale').valueAsNumber,color:$('#master-color').value};try{EmberAdvancedAuthoring.validate({master:m});stashLayer();for(const layer of layers)layer.effect.master={...m};state=layers[activeLayer].effect;persist();}catch(error){toast(error.message);refresh();}}
 for(const key of ['intensity','scale','color'])$('#master-'+key).onchange=master;
 $('#master-reset').onclick=()=>{for(const key of ['intensity','scale','color'])$('#master-'+key).value=EmberAdvancedAuthoring.defaults[key];master();};
 $('#layer-simulation').onchange=e=>{if(e.target.value==='gpu'&&state.eventRules?.length){toast('Event responses require CPU. Remove the rules before choosing GPU.');refresh();return;}state.simulation=e.target.value;if(state.simulation==='gpu')state.gpuAmount||=5000;refresh();persist();};$('#gpu-amount').onchange=e=>{if(e.target.checkValidity()){state.gpuAmount=e.target.valueAsNumber;persist();}};$('#scene-collision').onchange=e=>{if(e.target.value!=='off'&&state.motion==='orbit'){toast('Choose aimed or preset movement for scene collisions.');refresh();return;}state.sceneCollision=e.target.value;persist();};
 async function request(data){if(!window.emberDesktop)throw Error('Connect an Unreal project in the desktop app first.');const r=await emberDesktop.niagaraWorkspace({...data,project});if(!r.ok)throw Error(r.error);if(r.canceled)return;project=r.project;return r.result;}
 let busy=false;async function action(fn){if(busy)return;busy=true;const controls=['read-scene-assets','surface-asset','attachment-map','attachment-actor','attachment-socket'].map(id=>$('#'+id));controls.forEach(input=>input.disabled=true);const status=$('#scene-authoring-status');status.textContent='Reading Unreal project…';try{await fn();status.textContent='Ready. Scene-dependent behavior is simulated in Unreal.';}catch(error){status.textContent=error.message;}finally{busy=false;controls.forEach(input=>input.disabled=false);}}
 $('#read-scene-assets').onclick=()=>action(async()=>{const data=await request({action:'assets'});if(!data)return;assets=data.assets;const meshes=$('#surface-asset'),maps=$('#attachment-map');meshes.replaceChildren(new Option('Original spawn shape',''));maps.replaceChildren(new Option('Choose a level to read its actors',''));for(const a of assets){if(a.kind==='map')maps.add(new Option(a.name,a.asset));else meshes.add(new Option((a.kind==='skeletal'?'Character: ':'Mesh: ')+a.name,a.asset));}refresh();});
 $('#surface-asset').onchange=e=>action(async()=>{if(!e.target.value){delete state.surface;window.resetSelectedLayer();persist();return;}const target=state;const a=assets.find(a=>a.asset===e.target.value);if(!a)throw Error('Read this project’s assets again.');const data=await request({action:'surface',asset:a.asset});if(!data)return;if(state!==target)throw Error('The selected layer changed. Choose its surface again.');if(state.motion==='orbit')state.motion='aimed';state.surface={kind:a.kind,asset:a.asset,points:data.points};EmberAdvancedAuthoring.validate(state);sync();window.resetSelectedLayer();persist();});
 $('#attachment-map').onchange=e=>action(async()=>{if(!e.target.value)return;const data=await request({action:'scene',asset:e.target.value});if(!data)return;actors=data.actors;$('#attachment-actor').replaceChildren(new Option('No attachment',''));for(const a of actors)$('#attachment-actor').add(new Option(a.label,a.name));});
 $('#attachment-actor').onchange=e=>{const actor=actors.find(a=>a.name===e.target.value);$('#attachment-socket').replaceChildren(new Option('Actor / mesh origin',''));stashLayer();if(!actor){for(const layer of layers)delete layer.effect.attachment;}else{for(const layer of layers)layer.effect.attachment={actor:actor.name,socket:''};for(const socket of actor.sockets)$('#attachment-socket').add(new Option(socket,socket));}persist();};$('#attachment-socket').onchange=e=>{if(state.attachment){for(const layer of layers)if(layer.effect.attachment)layer.effect.attachment.socket=e.target.value;persist();}};
 $('#scene-authoring-help').onclick=()=>openDocumentation('scene-authoring');const previous=sync;sync=()=>{previous();refresh();};refresh();
})();
